def verifier(assign):
    # Basic structure and type checks
    if not isinstance(assign, dict):
        return (False, None)
    required = ['alpha', 'l1', 'l2', 'l3']
    for k in required:
        if k not in assign:
            # missing placeholders
            return (False, None)
        if not isinstance(assign[k], int):
            return (False, None)
        if assign[k] <= 0:
            return (False, None)
    alpha = assign['alpha']
    l1 = assign['l1']
    l2 = assign['l2']
    l3 = assign['l3']
    if alpha < 2:
        # too trivial / invalid
        return (False, None)
    # Derived moment targets from the telescoping ratios
    S1 = 3*l1 + 1
    S2 = 3*l2 + 1
    S3 = 3*l3 + 1
    # Difficulty-enforcing consistency: the three constraints must align with the
    # equal-case of Hölder/Maclaurin means for nonnegative variables:
    # S2 = S1^2/alpha and S3 = S1^3/alpha^2.
    if (S1*S1) % alpha != 0:
        return (False, None)
    if (S1*S1*S1) % (alpha*alpha) != 0:
        return (False, None)
    if S2 != (S1*S1)//alpha:
        return (False, None)
    if S3 != (S1*S1*S1)//(alpha*alpha):
        return (False, None)
    # With these constraints, the only feasible configuration has all x_n equal to c = S1/alpha,
    # and the minimal sum of fourth powers is fixed:
    # S4_min = alpha * c^4 = S1^4 / alpha^3.
    num = S1**4
    den = alpha**3
    from math import gcd
    g = gcd(num, den)
    num //= g
    den //= g
    if den == 1:
        ans = str(num)
    else:
        ans = f"{num}/{den}"
    return (True, ans)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

